# Let me find a rule that works on all THREE demos
# with equal row/column splits

def solve_with_equal_split(demo_name, inp, out):
    print(f"\n=== {demo_name} ===")

    positions = [(r, c) for r in range(7) for c in range(7) if inp[r][c] == 8]
    min_r, max_r = min(p[0] for p in positions), max(p[0] for p in positions)
    min_c, max_c = min(p[1] for p in positions), max(p[1] for p in positions)

    height = max_r - min_r + 1
    width = max_c - min_c + 1

    print(f"BB: h={height}, w={width}, rr={min_r}-{max_r}, cc={min_c}-{max_c}")

    # Try all possible split positions (floor, ceil, or something else)
    # For height H: split at row min_r + H//2 or min_r + (H+1)//2
    # For width W: split at col min_c + W//2 or min_c + (W+1)//2

    for split_method in ['floor', 'ceil']:
        top_rows = min_r + (height // 2) if split_method == 'floor' else min_r + (height - 1) // 2
        bottom_rows = set()
        for r in range(min_r, max_r+1):
            if r > top_rows:
                bottom_rows.add(r)

        left_cols = min_c + (width // 2) if split_method == 'floor' else min_c + (width - 1) // 2
        right_cols = set()
        for c in range(min_c, max_c+1):
            if c > left_cols:
                right_cols.add(c)

        # Test with color mapping
        # Try mapping: NW=1, NE=4, SW=3, SE=2
        test_colors = {'NW': 1, 'NE': 4, 'SW': 3, 'SE': 2}
        perfect = True
        mismatches = []

        for r, c in positions:
            if r <= top_rows and c <= left_cols:
                region = 'NW'
            elif r <= top_rows and c > left_cols:
                region = 'NE'
            elif r > top_rows and c <= left_cols:
                region = 'SW'
            else:
                region = 'SE'

            expected = test_colors[region]
            got = out[r][c]
            if expected != got:
                perfect = False
                mismatches.append(f"({r},{c}): {region} expected {expected}, got {got}")

        if perfect:
            print(f"  Found perfect split! top_rows={top_rows}, left_cols={left_cols}")
            return (top_rows, left_cols, test_colors)
        if not perfect:
            print(f"  Mismatches: {len(mismatches)} errors")

    return None

for name, inp, out in demos:
    result = solve_with_equal_split(name, inp, out)
    print(f"Result for {name}: {result}")

